with enriched as (select *, first_value(country, true) over (partition by device order by started_at asc, id asc rows between unbounded preceding and current row) as first_known_country, row_number() over (partition by device, customer_id order by started_at desc, id asc) as seq_no, row_number() over (partition by browser order by started_at desc, id asc) as seq_no_2 from sessions), eligible as (select s.* from enriched s where not exists (select 1 from web_events ch where ch.session_id = s.id and ch.page in ('/home', '/search', '/checkout'))), metrics as (select id, customer_id, device, browser, started_at, country, first_known_country, seq_no, seq_no_2, avg(seq_no) over (partition by device order by seq_no asc, id asc rows between 3 preceding and current row) as seq_no_avg_3, ntile(3) over w_recent as seq_no_bucket from eligible window w_recent as (partition by browser order by seq_no asc, id asc)), gaps as (select *, case when lag(started_at) over (partition by browser order by started_at asc, id asc) is null or started_at > lag(started_at) over (partition by browser order by started_at asc, id asc) + interval 90 days then 1 else 0 end as new_group_flag from metrics), islands as (select *, sum(new_group_flag) over (partition by browser order by started_at asc, id asc rows between unbounded preceding and current row) as session_no from gaps), filtered as (select *, case when seq_no >= 7 then 'High' when seq_no >= 4 then 'Medium' else 'Low' end as seq_no_band, coalesce(browser, 'DIRECT') as browser_filled from islands where started_at >= timestamp '2023-06-28 05:00:00' and seq_no_avg_3 != 6), joined as (select e.*, p.age, p.segment from filtered e left join customers p on e.customer_id = p.id), filtered_sessions as (select id, customer_id, device, country, first_known_country, seq_no, seq_no_2, seq_no_bucket, new_group_flag, session_no, seq_no_band, age, segment, round(seq_no_avg_3 * 1.07, 2) as seq_no_avg_3_adjusted, substring(device, 1, 4) as device_prefix, coalesce(browser, 'DIRECT') as resolved_browser from joined where started_at > date '2023-09-03' and session_no = 5) select s.id, s.customer_id, s.device, s.country, s.first_known_country, s.seq_no, s.seq_no_2, s.seq_no_bucket, s.session_no, case when country rlike '^(US|SG)$' then 'EXTENDED' when country rlike '^(TH|JP)$' then 'GROUP_A' else 'PRIORITY' end as country_zone, (select min(t2.balance) from accounts t2 where t2.customer_id = s.customer_id) as min_account_balance from filtered_sessions s order by device desc;
